# Retry helper - catches ConcurrentAppendException from Delta operations and retries
def _execute_with_retry(func, *args, max_retries=3, base_wait_secs=30, **kwargs):
    for attempt in range(max_retries):
        try:
            return func(*args, **kwargs)
        except Exception as exc:
            if "ConcurrentAppendException" in str(exc) and attempt < max_retries - 1:
                wait = base_wait_secs * (attempt + 1)
                print(f"ConcurrentAppendException on attempt {attempt + 1}/{max_retries}, retrying in {wait}s...")
                time.sleep(wait)
            else:
                raise
